import React, { useState } from "react";
import "./ScheduleTable.css";

const ScheduleTable = ({ schedule, title, showSala = true, editable = false }) => {
  const [showPopup, setShowPopup] = useState(false);
  const [selectedEntry, setSelectedEntry] = useState(null);
  const [scheduleData, setScheduleData] = useState(schedule);

  const handleEditClick = (entry) => {
    setSelectedEntry(entry);
    setShowPopup(true);
  };

  const closePopup = () => {
    setShowPopup(false);
    setSelectedEntry(null);
  };

  const handleDeleteEntry = () => {
    if (!selectedEntry) return;

    fetch(`http://localhost:34101/orar/${selectedEntry.id}`, {
      method: "DELETE",
    })
      .then((res) => {
        if (res.ok) {
          setScheduleData((prev) => prev.filter((item) => item.id !== selectedEntry.id));
          closePopup();
        } else {
          throw new Error("Ștergerea a eșuat");
        }
      })
      .catch((err) => console.error("Eroare la ștergere:", err));
  };

  const handleEditEntry = () => {
    if (!selectedEntry) return;

    const updatedEntry = {
      ...selectedEntry,
      disciplina: "Modificată Disciplina",
    };

    fetch(`http://localhost:34101/orar/${selectedEntry.id}`, {
      method: "PUT",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(updatedEntry),
    })
      .then((res) => res.json())
      .then((data) => {
        setScheduleData((prev) =>
          prev.map((item) => (item.id === selectedEntry.id ? data : item))
        );
        closePopup();
      })
      .catch((err) => console.error("Eroare la modificare:", err));
  };

  const handleAddNew = () => {
    const newEntry = {
      zi: "Luni",
      interval: "08:00 - 10:00",
      disciplina: "Nouă Disciplina",
      tip: "Curs",
      grupa: "A1",
      sala: "C101",
      profesor: "Profesor Nou",
      an: 1,
    };

    fetch("http://localhost:34101/orar", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(newEntry),
    })
      .then((res) => res.json())
      .then((data) => {
        setScheduleData((prevData) => [...prevData, data]);
        closePopup();
      })
      .catch((err) => console.error("Eroare la adăugare:", err));
  };

  if (!Array.isArray(schedule)) {
    return (
      <div className="schedule-table-container">
        <h2>{title}</h2>
        <p style={{ textAlign: "center" }}>Nu există date valide pentru acest orar.</p>
      </div>
    );
  }

  return (
    <div className="schedule-table-container">
      <h2>{title}</h2>
      <table className="schedule-table">
        <thead>
          <tr>
            <th>Zi</th>
            <th>Interval</th>
            <th>Disciplina</th>
            <th>Tip</th>
            <th>Grupa Studenților</th>
            {showSala && <th>Sală</th>}
            <th>Profesor</th>
            <th>An</th>
            {editable && <th>Acțiuni</th>}
          </tr>
        </thead>
        <tbody>
          {scheduleData.length === 0 ? (
            <tr>
              <td
                colSpan={showSala ? (editable ? 9 : 8) : (editable ? 8 : 7)}
                style={{ textAlign: "center" }}
              >
                Nu există date disponibile pentru afișare.
              </td>
            </tr>
          ) : (
            scheduleData.map((entry, index) => {
              return (
                <tr key={entry.id || index}>
                  <td>{entry.zi}</td>
                  <td>{entry.interval}</td>
                  <td>{entry.disciplina}</td>
                  <td>{entry.tip}</td>
                  <td>{entry.grupa || "-"}</td>
                  {showSala && <td>{entry.sala}</td>}
                  <td>{entry.profesor || "-"}</td>
                  <td>{entry.an || "-"}</td>
                  {editable && (
                    <td>
                      <button className="edit-button" onClick={() => handleEditClick(entry)}>
                        ✏️ Editare
                      </button>
                    </td>
                  )}
                </tr>
              );
            })
          )}
        </tbody>
      </table>

      {showPopup && (
        <div className="popup-overlay">
          <div className="popup-content">
            <h3>Alege o acțiune</h3>
            <p>Editezi rândul: {selectedEntry?.disciplina}</p>
            <button onClick={handleAddNew}>➕ Adaugă Nou</button>
            <button onClick={handleEditEntry}>✏️ Modifică</button>
            <button onClick={handleDeleteEntry}>🗑️ Șterge</button>
            <button onClick={closePopup}>Închide</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default ScheduleTable;
